/**
 * Dynamic Themes theme engine
 * id: mosaic-neon-fans-engine
 * kind: mosaic
 */
(function (global) {
  const enginesApi = global.BGThemeEngines;
  if (!enginesApi || typeof enginesApi.define !== "function") {
    throw new Error("BGThemeEngines is not loaded before mosaic-neon-fans-engine.js");
  }

  const DOTS_URI = 'url("data:image/webp;base64,")';
  const SHARDS_URI = 'url("data:image/webp;base64,")';
  const ASPECT_P = 3 / 4;
  const ASPECT_S = 1;
  const COUNT = 36;

  function uniqueUrls(pool) {
    const out = [];
    const seen = new Set();
    (pool || []).forEach(function (src) {
      if (!src || seen.has(src)) return;
      seen.add(src);
      out.push(src);
    });
    return out;
  }

  function isPortrait(root) {
    return !!(root && root.classList && root.classList.contains("dyn-portrait"));
  }

  function rand(a, b) {
    return a + Math.random() * (b - a);
  }

  function ensureSpin(card) {
    let spin = card.querySelector(".spin");
    if (!spin) {
      spin = document.createElement("div");
      spin.className = "spin";
      while (card.firstChild) spin.appendChild(card.firstChild);
      card.appendChild(spin);
    }
    let drift = spin.querySelector(".drift");
    let rock = spin.querySelector(".rock");
    if (!drift) {
      drift = document.createElement("div");
      drift.className = "drift";
      if (rock) {
        spin.insertBefore(drift, rock);
        drift.appendChild(rock);
      } else {
        while (spin.firstChild) drift.appendChild(spin.firstChild);
        spin.appendChild(drift);
      }
    }
    if (!drift.querySelector(".rock")) {
      rock = document.createElement("div");
      rock.className = "rock";
      while (drift.firstChild) rock.appendChild(drift.firstChild);
      drift.appendChild(rock);
    }
    ensureRing(card);
  }

  function ensureRing(card) {
    const rock = card.querySelector(".rock");
    if (!rock) return;
    let well = rock.querySelector(":scope > .well");
    if (!well) {
      well = document.createElement("div");
      well.className = "well";
      const img = rock.querySelector(":scope > img");
      if (img) well.appendChild(img);
      rock.insertBefore(well, rock.firstChild);
    }
    const photos = well.querySelectorAll("img");
    if (photos.length < 2) {
      const twin = document.createElement("img");
      twin.alt = "";
      twin.className = "is-back";
      if (photos[0] && photos[0].src) twin.src = photos[0].src;
      well.appendChild(twin);
    }
    let ring = rock.querySelector(":scope > .ring");
    if (!ring) {
      ring = document.createElement("div");
      ring.className = "ring";
      ring.appendChild(document.createElement("i"));
      rock.appendChild(ring);
    }
    if (!ring.querySelector("b")) ring.appendChild(document.createElement("b"));
    if (card.dataset.nfFrame) return;
    const n = card._nfOrder || 0;
    card.dataset.nfFrame = String(n % 5);
    card.style.setProperty("--nf-dur", (7.5 + (n % 5) * 1.7).toFixed(1) + "s");
    card.style.setProperty("--nf-delay", ((n % 8) * -0.85).toFixed(2) + "s");
    card.style.setProperty("--nf-dir", n % 2 ? "reverse" : "normal");
  }

  function applyCard(card, stage, x, y, w, h, yaw, z, isHero, square) {
    const W = stage.clientWidth;
    const H = stage.clientHeight;
    card.style.left = ((x / W) * 100).toFixed(3) + "%";
    card.style.top = ((y / H) * 100).toFixed(3) + "%";
    card.style.width = ((w / W) * 100).toFixed(3) + "%";
    card.style.height = ((h / H) * 100).toFixed(3) + "%";
    card.classList.toggle("is-hero", !!isHero);
    card.classList.toggle("is-square", !isHero && !!square);
    card.style.zIndex = isHero ? "12" : "3";
    writeFrameBox(card, w, h, stage._nfBorder);
    const spin = card.querySelector(".spin");
    if (spin) {
      spin.style.setProperty("--yaw", (isHero ? 0 : yaw).toFixed(2) + "deg");
      spin.style.setProperty("--z", (isHero ? 20 : z).toFixed(1) + "px");
    }
  }

  function textureCanvas(width, height, paint) {
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    const image = ctx.createImageData(width, height);
    paint(image.data, width, height);
    ctx.putImageData(image, 0, 0);
    return 'url("' + canvas.toDataURL("image/png") + '")';
  }

  function ensureTextures(themeRoot) {
    if (!themeRoot || !themeRoot.style) return;
    if (themeRoot.style.getPropertyValue("--nf-tex-grain")) return;
    themeRoot.style.setProperty("--nf-tex-soft", textureCanvas(96, 96, function (data) {
      for (let i = 0; i < data.length; i += 4) {
        const n = 112 + Math.random() * 32;
        data[i] = n;
        data[i + 1] = n;
        data[i + 2] = n;
        data[i + 3] = 255;
      }
    }));
    themeRoot.style.setProperty("--nf-tex-grain", textureCanvas(96, 96, function (data) {
      for (let i = 0; i < data.length; i += 4) {
        const n = 60 + Math.random() * 140;
        data[i] = n;
        data[i + 1] = n;
        data[i + 2] = n;
        data[i + 3] = 255;
      }
    }));
    themeRoot.style.setProperty("--nf-tex-wave", textureCanvas(180, 96, function (data, width, height) {
      const kx = Math.PI * 2 * 3 / width;
      const ky = Math.PI * 2 * 2 / height;
      for (let y = 0; y < height; y += 1) {
        for (let x = 0; x < width; x += 1) {
          const i = (y * width + x) * 4;
          const wave = Math.sin(x * kx) * 0.62 + Math.sin(y * ky + x * kx) * 0.38;
          const n = 128 + wave * 96;
          data[i] = n;
          data[i + 1] = n;
          data[i + 2] = n;
          data[i + 3] = 255;
        }
      }
    }));
    themeRoot.style.setProperty("--nf-tex-bold", textureCanvas(128, 128, function (data, width, height) {
      for (let i = 0; i < data.length; i += 4) {
        data[i] = 148;
        data[i + 1] = 148;
        data[i + 2] = 148;
        data[i + 3] = 255;
      }
      function splat(cx, cy, rad, ink) {
        const reach = Math.ceil(rad);
        for (let oy = -reach; oy <= reach; oy += 1) {
          for (let ox = -reach; ox <= reach; ox += 1) {
            const dist = Math.sqrt(ox * ox + oy * oy);
            if (dist > rad) continue;
            const fall = Math.pow(1 - dist / rad, 1.7);
            const x = ((Math.round(cx + ox) % width) + width) % width;
            const y = ((Math.round(cy + oy) % height) + height) % height;
            const i = (y * width + x) * 4;
            const next = data[i] + (ink - data[i]) * fall;
            data[i] = next;
            data[i + 1] = next;
            data[i + 2] = next;
          }
        }
      }
      for (let n = 0; n < 46; n += 1) {
        splat(Math.random() * width, Math.random() * height, 4 + Math.random() * 10, Math.random() < 0.5 ? 28 : 230);
      }
    }));
  }

  function applyTexture(themeRoot, settings) {
    if (!themeRoot) return;
    const name = settings && settings.texture;
    themeRoot.dataset.texture = name === "soft" || name === "wave" || name === "bold" ? name : "grain";
  }

  function shownPhoto(card) {
    const well = card && card.querySelector(".well");
    if (!well) return card && card.querySelector("img");
    return well.querySelector("img:not(.is-back)") || well.querySelector("img");
  }

  function nextPhoto(state, img) {
    const api = state && state.api;
    const current = img && (img.currentSrc || img.src);
    if (api && typeof api.nextUrl === "function") return api.nextUrl(current) || "";
    const pool = (state && state.pool) || [];
    if (!pool.length) return "";
    let src = pool[Math.floor(Math.random() * pool.length)];
    if (pool.length > 1 && src === current) src = pool[(pool.indexOf(src) + 1) % pool.length];
    return src || "";
  }

  function photoLocked(state, card) {
    if (!state || !card) return true;
    const index = state.cards.indexOf(card);
    if (index < 0) return true;
    if (index === state.heroIndex) return true;
    if (state.busy && index === state.leavingIndex) return true;
    return false;
  }

  function dissolvePhoto(state, card, src) {
    if (!card || card._nfDissolving || photoLocked(state, card) || !src) return;
    const well = card.querySelector(".well");
    if (!well) return;
    const shown = well.querySelector("img:not(.is-back)");
    const hidden = well.querySelector("img.is-back");
    if (!shown || !hidden) return;
    const current = shown.currentSrc || shown.src;
    if (current && src === current) return;
    card._nfDissolving = true;
    function reveal() {
      hidden.removeEventListener("load", reveal);
      if (photoLocked(state, card)) {
        card._nfDissolving = false;
        return;
      }
      hidden.style.zIndex = "2";
      hidden.classList.remove("is-back");
      window.setTimeout(function () {
        shown.style.transition = "none";
        shown.classList.add("is-back");
        shown.style.zIndex = "0";
        hidden.style.zIndex = "1";
        void shown.offsetWidth;
        shown.style.transition = "";
        card._nfDissolving = false;
      }, 920);
    }
    hidden.addEventListener("load", reveal);
    if (hidden.src === src && hidden.complete && hidden.naturalWidth) reveal();
    else hidden.src = src;
  }

  function cycleBackground(state) {
    if (!state || !state.alive || !state.cards) return;
    const open = [];
    state.cards.forEach(function (card) {
      if (photoLocked(state, card) || card._nfDissolving) return;
      open.push(card);
    });
    if (open.length) {
      const card = open[Math.floor(Math.random() * open.length)];
      dissolvePhoto(state, card, nextPhoto(state, shownPhoto(card)));
    }
    state.cycleTimer = window.setTimeout(function () {
      cycleBackground(state);
    }, 1600 + Math.random() * 1400);
  }

  function borderFactor(settings) {
    const n = Number(settings && settings.border);
    const value = isFinite(n) ? n : 0.5;
    return Math.max(0.12, Math.min(1, value));
  }

  function writeFrameBox(card, w, h, factor) {
    const amount = isFinite(factor) ? factor : 0.5;
    const short = Math.min(w, h);
    const stroke = Math.max(1.5, w * 0.1 * amount);
    const radius = Math.max(3, short * 0.12);
    card.style.setProperty("--nf-stroke", stroke.toFixed(1) + "px");
    card.style.setProperty("--nf-radius", radius.toFixed(1) + "px");
    card.style.setProperty("--nf-inset", (stroke + Math.max(2, short * 0.015)).toFixed(1) + "px");
  }

  function paintBorders(state) {
    if (!state || !state.stage || !state.cards) return;
    const factor = borderFactor(state.settings);
    state.stage._nfBorder = factor;
    state.cards.forEach(function (card) {
      const w = card.clientWidth;
      const h = card.clientHeight;
      if (w < 2 || h < 2) return;
      writeFrameBox(card, w, h, factor);
    });
  }

  function cardShape(card) {
    if (!card.dataset.nfShape) card.dataset.nfShape = Math.random() < 0.32 ? "sq" : "p";
    return card.dataset.nfShape;
  }

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      const t = arr[i];
      arr[i] = arr[j];
      arr[j] = t;
    }
    return arr;
  }

  function clampChromeScale(value) {
    const n = Number(value);
    if (!isFinite(n) || n <= 0) return 1;
    return Math.max(0.5, Math.min(1.8, n));
  }

  function applyChromeScale(themeRoot, settings) {
    if (!themeRoot) return;
    const logoOn = themeRoot.classList.contains("dyn-show-logo");
    const qrOn = themeRoot.classList.contains("dyn-show-qr");
    const logoN = logoOn ? clampChromeScale(settings && settings.logoScale) : 1;
    const qrN = qrOn ? clampChromeScale(settings && settings.qrScale) : 1;
    const logo = themeRoot.querySelector("[data-logo]");
    const qr = themeRoot.querySelector("[data-qr]");
    if (logo) {
      logo.style.transformOrigin = "top left";
      logo.style.transform = Math.abs(logoN - 1) < 0.015 ? "" : "scale(" + logoN.toFixed(2) + ")";
    }
    if (qr) {
      qr.style.transformOrigin = "bottom right";
      qr.style.transform = Math.abs(qrN - 1) < 0.015 ? "" : "scale(" + qrN.toFixed(2) + ")";
    }
  }

  function brandKeepouts(root, stage) {
    if (!root || !stage) return [];
    const stageBox = stage.getBoundingClientRect();
    const boxes = [];
    function push(selector, on, fallbackRatio) {
      if (!on) return;
      const el = root.querySelector(selector);
      if (!el || el.hidden) return;
      const r = el.getBoundingClientRect();
      const w = r.width;
      const h = r.height > 8 ? r.height : w * fallbackRatio;
      if (w < 8 || h < 8) return;
      const inset = Math.min(w, h) * 0.16;
      boxes.push({
        x: r.left - stageBox.left + inset,
        y: r.top - stageBox.top + inset,
        w: Math.max(8, w - inset * 2),
        h: Math.max(8, h - inset * 2)
      });
    }
    push("[data-logo]", root.classList.contains("dyn-show-logo"), 0.62);
    push("[data-qr]", root.classList.contains("dyn-show-qr"), 1);
    return boxes;
  }

  function coveredByChrome(box, keepouts) {
    if (!keepouts || !keepouts.length) return false;
    const area = box.w * box.h;
    if (!(area > 0)) return false;
    for (let i = 0; i < keepouts.length; i += 1) {
      const k = keepouts[i];
      const ix = Math.min(box.x + box.w, k.x + k.w) - Math.max(box.x, k.x);
      const iy = Math.min(box.y + box.h, k.y + k.h) - Math.max(box.y, k.y);
      if (ix > 0 && iy > 0 && (ix * iy) / area > 0.22) return true;
    }
    return false;
  }

  function packRegion(cards, stage, rect, stageW, heroW, heroH, keepouts) {
    if (!cards.length || rect.w < 8 || rect.h < 8) return;
    const pad = Math.max(2, stageW * 0.002);
    const items = cards.slice().sort(function (a, b) {
      return (a._nfOrder || 0) - (b._nfOrder || 0);
    }).map(function (card) {
      const square = cardShape(card) === "sq";
      if (!card._nfSpots) {
        const spots = [];
        const seed = (card._nfOrder || 0) + 1;
        let u = (seed * 0.37) % 1;
        let v = (seed * 0.61) % 1;
        for (let t = 0; t < 28; t += 1) {
          spots.push({ u: u, v: v });
          u = (u + 0.19) % 1;
          v = (v + 0.27) % 1;
        }
        card._nfSpots = spots;
        card._nfWeight = 0.72 + (seed % 6) * 0.06;
      }
      return {
        card: card,
        aspect: square ? ASPECT_S : ASPECT_P,
        square: square,
        weight: card._nfWeight,
        spots: card._nfSpots
      };
    });

    function overlaps(a, b, g) {
      const m = g == null ? pad : g;
      return a.x < b.x + b.w + m && a.x + a.w + m > b.x && a.y < b.y + b.h + m && a.y + a.h + m > b.y;
    }

    function tryPack(S) {
      const placed = [];
      for (let i = 0; i < items.length; i += 1) {
        const it = items[i];
        const w = S * it.weight;
        const h = w / it.aspect;
        if (w > rect.w - pad * 2 || h > rect.h - pad * 2) return null;
        const minX = rect.x + pad;
        const minY = rect.y + pad;
        const spanX = rect.x + rect.w - w - pad - minX;
        const spanY = rect.y + rect.h - h - pad - minY;
        if (spanX < 0 || spanY < 0) return null;
        let found = null;
        for (let t = 0; t < it.spots.length; t += 1) {
          const box = {
            x: minX + it.spots[t].u * spanX,
            y: minY + it.spots[t].v * spanY,
            w: w,
            h: h
          };
          let hit = false;
          for (let p = 0; p < placed.length; p += 1) {
            if (overlaps(box, placed[p])) {
              hit = true;
              break;
            }
          }
          if (!hit && !coveredByChrome(box, keepouts)) {
            found = box;
            break;
          }
        }
        if (!found) return null;
        found.it = it;
        placed.push(found);
      }
      return placed;
    }

    let lo = 6;
    let hi = Math.min(rect.w, rect.h, heroW * 0.82, heroH * 0.82);
    let best = null;
    for (let k = 0; k < 16; k += 1) {
      const mid = (lo + hi) / 2;
      const packed = tryPack(mid);
      if (packed) {
        best = packed;
        lo = mid;
      } else {
        hi = mid;
      }
    }
    const placed = best || tryPack(Math.max(6, lo * 0.85));
    if (!placed) return;
    const maxW = heroW * 0.8;
    const maxH = heroH * 0.8;
    placed.forEach(function (p) {
      let loS = 1;
      let hiS = 1.65;
      let bestS = 1;
      for (let k = 0; k < 8; k += 1) {
        const mid = (loS + hiS) / 2;
        const box = { x: p.x, y: p.y, w: p.w * mid, h: p.h * mid };
        if (
          box.w > maxW ||
          box.h > maxH ||
          box.x + box.w > rect.x + rect.w - pad ||
          box.y + box.h > rect.y + rect.h - pad ||
          coveredByChrome(box, keepouts)
        ) {
          hiS = mid;
          continue;
        }
        let hit = false;
        for (let i = 0; i < placed.length; i += 1) {
          if (placed[i] === p) continue;
          if (overlaps(box, placed[i], pad * 0.7)) {
            hit = true;
            break;
          }
        }
        if (hit) hiS = mid;
        else {
          bestS = mid;
          loS = mid;
        }
      }
      p.w *= bestS;
      p.h *= bestS;
    });
    placed.forEach(function (p) {
      const yaw = ((p.x + p.w * 0.5) / stageW - 0.5) * 10;
      applyCard(p.it.card, stage, p.x, p.y, p.w, p.h, yaw, 0, false, p.it.square);
    });
  }

  function layout(state) {
    const stage = state.stage;
    if (!stage || !stage.clientWidth) return;
    stage._nfBorder = borderFactor(state.settings);
    const W = stage.clientWidth;
    const H = stage.clientHeight;
    const portrait = isPortrait(state.root);
    const photo = photoScale(state.root);
    const grow = state.heroGrow || 1;
    let heroW = (portrait ? Math.min(W * 0.5, H * 0.4) : Math.min(W * 0.28, H * 0.58)) * photo * grow;
    let heroH = heroW / ASPECT_P;
    const minBand = H * (portrait ? 0.1 : 0.072);
    const minSide = W * (portrait ? 0.08 : 0.11);
    if (heroH > H - minBand * 2) {
      heroH = H - minBand * 2;
      heroW = heroH * ASPECT_P;
    }
    if (heroW > W - minSide * 2) {
      heroW = W - minSide * 2;
      heroH = heroW / ASPECT_P;
    }
    const heroX = (W - heroW) / 2;
    const heroY = (H - heroH) / 2;
    const hero = state.cards[state.heroIndex];
    applyCard(hero, stage, heroX, heroY, heroW, heroH, 0, 20, true, false);
    const keepouts = brandKeepouts(state.root, stage);

    const bins = { n: [], s: [], w: [], e: [] };
    state.cards.forEach(function (card, i) {
      if (i === state.heroIndex) return;
      const key = bins[state.wing[i]] ? state.wing[i] : "e";
      bins[key].push(card);
    });
    const bandRoom = Math.max(H * 0.2, heroH * 0.26);
    if (heroY < bandRoom) {
      bins.n.forEach(function (card, i) {
        bins[i % 2 ? "e" : "w"].push(card);
      });
      bins.s.forEach(function (card, i) {
        bins[i % 2 ? "w" : "e"].push(card);
      });
      bins.n = [];
      bins.s = [];
    }
    const regions = {
      n: { x: heroX, y: 0, w: heroW, h: heroY },
      s: { x: heroX, y: heroY + heroH, w: heroW, h: H - heroY - heroH },
      w: { x: 0, y: 0, w: heroX, h: H },
      e: { x: heroX + heroW, y: 0, w: W - heroX - heroW, h: H }
    };
    Object.keys(bins).forEach(function (key) {
      packRegion(bins[key], stage, regions[key], W, heroW, heroH, keepouts);
    });
  }

  function firstRects(cards) {
    return cards.map(function (card) {
      return card.getBoundingClientRect();
    });
  }

  function playFlip(cards, before, timing) {
    const pace = timing || {};
    const pending = [];
    cards.forEach(function (card, i) {
      const last = card.getBoundingClientRect();
      const first = before[i];
      if (!first || !last.width || !last.height) return;
      const dx = first.left - last.left;
      const dy = first.top - last.top;
      const sx = first.width / last.width;
      const sy = first.height / last.height;
      if (Math.abs(dx) < 1.5 && Math.abs(dy) < 1.5 && Math.abs(sx - 1) < 0.03 && Math.abs(sy - 1) < 0.03) {
        card.style.transition = "";
        card.style.transform = "";
        return;
      }
      card.style.transition = "none";
      card.style.transform =
        "translate(" + dx.toFixed(2) + "px," + dy.toFixed(2) + "px) scale(" + sx.toFixed(4) + "," + sy.toFixed(4) + ")";
      pending.push({
        card: card,
        delay: pace.delayFor ? pace.delayFor(i) : 0,
        duration: pace.durationFor ? pace.durationFor(i) : 1.8
      });
    });
    if (!pending.length) return;
    void pending[0].card.offsetWidth;
    pending.forEach(function (item) {
      item.card.style.transition =
        "transform " + item.duration + "s " + item.delay + "s cubic-bezier(0.22, 0.82, 0.28, 1)";
      item.card.style.transform = "translate(0,0) scale(1,1)";
    });
  }

  function assignWings(count, heroIndex) {
    const wing = [];
    const sats = [];
    for (let i = 0; i < count; i += 1) {
      if (i === heroIndex) wing[i] = "hero";
      else sats.push(i);
    }
    sats.forEach(function (i, slot) {
      if (slot < 2) wing[i] = "n";
      else if (slot < 4) wing[i] = "s";
      else wing[i] = slot % 2 === 0 ? "e" : "w";
    });
    return wing;
  }

  function photoScale(root) {
    const n = parseFloat(root && getComputedStyle(root).getPropertyValue("--scale"));
    if (!isFinite(n) || n <= 0) return 1;
    return Math.max(0.72, Math.min(1.28, n));
  }

  function pinScene(themeRoot) {
    const nf = themeRoot && themeRoot.querySelector(".nf");
    if (nf) nf.style.transform = "none";
  }

  function installPerfStyle() {
    if (document.getElementById("nf-perf-style")) return;
    const style = document.createElement("style");
    style.id = "nf-perf-style";
    style.textContent = [
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .nf{transform:none!important;}',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dyn-card,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dyn-card .spin,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dyn-card .drift,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dyn-card .rock,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .sky,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dots,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .shards,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .gleam{will-change:auto!important;}',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dyn-card .rock,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dots,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .shards,',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .gleam{animation:none!important;}',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .sky{animation:nf-zoom 46s ease-in-out infinite!important;}',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dyn-card .drift{animation:nf-float-a 36s ease-in-out infinite!important;}',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dyn-card:nth-child(odd) .drift{animation-delay:-12s!important;}',
      '#dyn-mosaic-theme[data-theme="mosaic-neon-fans"] .dyn-card:nth-child(3n) .drift{animation-delay:-20s!important;}'
    ].join("");
    (document.head || document.documentElement).appendChild(style);
  }

  function applyHue(themeRoot, settings) {
    if (!themeRoot || !themeRoot.style) return;
    const blue = (settings && settings.primary) || "#2ee6ff";
    const pink = (settings && settings.secondary) || "#ff3dca";
    const voidColor = (settings && settings.background) || "#050814";
    if (enginesApi.differs && enginesApi.differs(voidColor, "#050814")) themeRoot.dataset.void = "1";
    else delete themeRoot.dataset.void;
    if (typeof enginesApi.colorizeDuo !== "function") return;
    const key = blue + "|" + pink;
    if (themeRoot._nfLightKey === key) return;
    window.clearTimeout(themeRoot._nfBitmapTimer);
    themeRoot._nfBitmapTimer = window.setTimeout(function () {
      themeRoot._nfLightKey = key;
      const token = (themeRoot._nfBitmap = (themeRoot._nfBitmap || 0) + 1);
      [
        ["--dots-img", "neon-dots", DOTS_URI],
        ["--shards-img", "neon-shards", SHARDS_URI]
      ].forEach(function (job) {
        enginesApi.colorizeDuo(job[1], job[2], "#2ee6ff", blue, "#ff3dca", pink, "").then(function (url) {
          if (!url || themeRoot._nfBitmap !== token) return;
          themeRoot.style.setProperty(job[0], 'url("' + url + '")');
        }).catch(function () {});
      });
    }, 160);
  }

  enginesApi.define({
    id: "mosaic-neon-fans-engine",
    kind: "mosaic",
    interval: 9000,

    mount(themeRoot, pool, hostApi, settings) {
      const mosaicApi = global.BGMosaicThemes || {};
      const makeCard =
        mosaicApi.makeCard ||
        function (src) {
          const card = document.createElement("div");
          card.className = "dyn-card";
          const img = document.createElement("img");
          img.alt = "";
          img.src = src || "";
          card.appendChild(img);
          return card;
        };

      let shell = themeRoot.querySelector(".nf");
      if (!shell) {
        themeRoot.innerHTML =
          '<div class="nf"><div class="bg"><div class="sky"></div><div class="dots"></div><div class="shards"></div><div class="gleam"></div><div class="sweeps" aria-hidden="true"><i class="bar a"></i><i class="bar b"></i><i class="bar c"></i><i class="orb a"></i><i class="orb b"></i><i class="orb c"></i><i class="wash"></i></div></div><div class="stage"></div><div class="fx" aria-hidden="true"><i class="streak a"></i><i class="streak b"></i><i class="ghost a"></i><i class="ghost b"></i><i class="ghost c"></i><i class="bloom"></i></div><div class="logo-slot" data-logo></div><div class="qr-slot" data-qr></div></div>';
        shell = themeRoot.querySelector(".nf");
      }
      themeRoot.style.setProperty("--dots-img", DOTS_URI);
      themeRoot.style.setProperty("--shards-img", SHARDS_URI);
      installPerfStyle();
      pinScene(themeRoot);
      ensureTextures(themeRoot);
      applyTexture(themeRoot, settings);
      applyHue(themeRoot, settings);
      const stage = shell.querySelector(".stage");
      const urls = uniqueUrls(pool);
      const cards = [];
      for (let i = 0; i < COUNT; i += 1) {
        const src = urls.length ? urls[i % urls.length] : "";
        const card = makeCard(src);
        card.style.position = "absolute";
        card.style.margin = "0";
        card._nfOrder = i;
        ensureSpin(card);
        stage.appendChild(card);
        cards.push(card);
      }

      const state = {
        root: themeRoot,
        stage: stage,
        cards: cards,
        api: hostApi,
        heroIndex: 0,
        wing: assignWings(COUNT, 0),
        heroGrow: 1,
        busy: false,
        alive: true,
        leavingIndex: -1,
        pool: urls,
        ro: null,
        settings: settings || {}
      };
      state.onChrome = function () {
        applyChromeScale(themeRoot, state.settings);
        if (!state.busy) layout(state);
      };
      themeRoot.addEventListener("dyn-chrome-scale", state.onChrome);
      layout(state);
      state._nfScale = photoScale(themeRoot);
      cycleBackground(state);
      if (typeof ResizeObserver !== "undefined") {
        state.ro = new ResizeObserver(function () {
          if (state.busy) return;
          const w = stage.clientWidth;
          const h = stage.clientHeight;
          if (w === state.seenW && h === state.seenH) return;
          state.seenW = w;
          state.seenH = h;
          layout(state);
        });
        state.ro.observe(stage);
      }
      return state;
    },

    applySettings(themeRoot, state, settings) {
      installPerfStyle();
      pinScene(themeRoot);
      ensureTextures(themeRoot);
      applyTexture(themeRoot, settings);
      applyHue(themeRoot, settings);
      if (state) {
        state.settings = settings || state.settings || {};
        applyChromeScale(themeRoot, state.settings);
        const nextScale = photoScale(themeRoot);
        const nextBorder = borderFactor(state.settings);
        const scaleChanged = !state._nfScale || Math.abs(state._nfScale - nextScale) > 0.001;
        const borderChanged = state._nfBorder == null || Math.abs(state._nfBorder - nextBorder) > 0.001;
        state._nfScale = nextScale;
        state._nfBorder = nextBorder;
        if (scaleChanged) layout(state);
        else if (borderChanged) paintBorders(state);
      }
    },

    tick(_themeRoot, pool, state, hostApi) {
      if (!state || !state.cards || state.cards.length < 2 || state.busy) return;
      if (hostApi) state.api = hostApi;
      if (pool && pool.length) state.pool = uniqueUrls(pool);
      const n = state.cards.length;
      const prev = state.heroIndex;
      let next = prev;
      let guard = 0;
      while ((next === prev || state.cards[next]._nfDissolving) && guard < n * 2) {
        next = Math.floor(Math.random() * n);
        guard += 1;
      }
      if (next === prev) return;
      const before = firstRects(state.cards);
      state.leavingIndex = prev;
      state.wing[prev] = state.wing[next] === "hero" ? "left" : state.wing[next];
      state.wing[next] = "hero";
      state.heroIndex = next;
      state.heroGrow = 1;
      layout(state);
      const incoming = state.cards[next];
      if (incoming) incoming.style.zIndex = "4";
      state.busy = true;
      const leaveS = 1.85;
      const enterDelayS = 1.55;
      const enterS = 2.05;
      playFlip(state.cards, before, {
        delayFor: function (i) {
          return i === next ? enterDelayS : 0;
        },
        durationFor: function (i) {
          return i === next ? enterS : leaveS;
        }
      });
      window.setTimeout(function () {
        if (incoming && state.heroIndex === next) incoming.style.zIndex = "12";
      }, enterDelayS * 1000);
      window.setTimeout(function () {
        state.leavingIndex = -1;
        const card = state.cards[prev];
        if (!card || state.heroIndex === prev) return;
        dissolvePhoto(state, card, nextPhoto(state, shownPhoto(card)));
      }, leaveS * 1000 + 60);
      window.setTimeout(function () {
        state.busy = false;
        state.leavingIndex = -1;
        state.cards.forEach(function (card) {
          card.style.transition = "";
          card.style.transform = "";
        });
      }, (enterDelayS + enterS) * 1000 + 80);
    },

    unmount(themeRoot, state) {
      if (state && state.onChrome && themeRoot) {
        themeRoot.removeEventListener("dyn-chrome-scale", state.onChrome);
      }
      if (state) {
        state.alive = false;
        window.clearTimeout(state.cycleTimer);
        state.cycleTimer = 0;
      }
      if (state && state.ro) {
        try {
          state.ro.disconnect();
        } catch (err) {}
        state.ro = null;
      }
      if (themeRoot) themeRoot.replaceChildren();
    }
  });
})(typeof globalThis !== "undefined" ? globalThis : window);
